194→/// Build the docker create arguments (for testing).
195→pub fn build_create_args(
196→    name: &str,
197→    workspace_dir: &Path,
198→    image: &str,
199→    env: &HashMap<String, String>,
200→    anonymous_volumes: &[String],
201→) -> Vec<String> {
202→    let mut args = vec![
203→        "create".to_string(),
204→        "--name".to_string(),
205→        name.to_string(),
206→        // Bind mount workspace
207→        "-v".to_string(),
208→        format!("{}:{WORKSPACE_MOUNT}", workspace_dir.display()),
209→    ];
210→
211→    // Anonymous volumes for directory isolation
212→    for vol in anonymous_volumes {
213→        args.push("-v".to_string());
214→        args.push(format!("{WORKSPACE_MOUNT}/{vol}"));
215→    }
216→
217→    // Environment variables
218→    for (key, value) in env {
219→        args.push("-e".to_string());
220→        args.push(format!("{key}={value}"));
221→    }
222→
223→    // Working directory
224→    args.push("-w".to_string());
225→    args.push(WORKSPACE_MOUNT.to_string());
226→
227→    // Image
228→    args.push(image.to_string());
229→
230→    // Keep container running for docker exec
231→    args.push("sleep".to_string());
232→    args.push("infinity".to_string());
233→
234→    args
235→}
