  4→/// Create a minimal monorepo fixture as a local git repo.
  5→///
  6→/// The fixture contains:
  7→/// - `package.json` with a start script
  8→/// - `server.js` — minimal Node.js HTTP server on port 3000
  9→/// - An initial git commit so `git clone --local` works
 10→///
 11→/// Returns the path to the fixture repo directory.
 12→pub fn create_fixture_repo(parent_dir: &Path) -> PathBuf {
 13→    let repo_dir = parent_dir.join("fixture-repo");
 14→    std::fs::create_dir_all(&repo_dir).expect("failed to create fixture repo dir");
 15→
 16→    // Initialize git repo
 17→    let output = Command::new("git")
 18→        .args(["init", "--initial-branch", "main"])
 19→        .current_dir(&repo_dir)
 20→        .output()
 21→        .expect("git not found");
 22→    assert!(output.status.success(), "git init failed");
 23→
 24→    // Configure git user for commits
 25→    let _ = Command::new("git")
 26→        .args(["config", "user.email", "test@dual.dev"])
 27→        .current_dir(&repo_dir)
 28→        .output();
 29→    let _ = Command::new("git")
 30→        .args(["config", "user.name", "Dual Test"])
 31→        .current_dir(&repo_dir)
 32→        .output();
 33→
 34→    // Create package.json
 35→    let package_json = r#"{
 36→  "name": "dual-test-fixture",
 37→  "version": "0.0.1",
 38→  "scripts": {
 39→    "start": "node server.js",
 40→    "dev": "node server.js"
 41→  }
 42→}
 43→"#;
 44→    std::fs::write(repo_dir.join("package.json"), package_json)
 45→        .expect("failed to write package.json");
 46→
 47→    // Create server.js — minimal HTTP server
 48→    let server_js = r#"const http = require("http");
 49→const server = http.createServer((req, res) => {
 50→  res.writeHead(200, { "Content-Type": "text/plain" });
 51→  res.end("dual-test-ok\n");
 52→});
 53→server.listen(3000, () => {
 54→  console.log("listening on :3000");
 55→});
 56→"#;
 57→    std::fs::write(repo_dir.join("server.js"), server_js).expect("failed to write server.js");
 58→
 59→    // Git add and commit
 60→    let output = Command::new("git")
 61→        .args(["add", "."])
 62→        .current_dir(&repo_dir)
 63→        .output()
 64→        .expect("git add failed");
 65→    assert!(output.status.success(), "git add failed");
 66→
 67→    let output = Command::new("git")
 68→        .args(["commit", "-m", "initial fixture"])
 69→        .current_dir(&repo_dir)
 70→        .output()
 71→        .expect("git commit failed");
 72→    assert!(
 73→        output.status.success(),
 74→        "git commit failed: {}",
 75→        String::from_utf8_lossy(&output.stderr)
 76→    );
 77→
 78→    repo_dir
 79→}
