 27→/// Routing entry: subdomain → container IP.
 28→type RouteMap = HashMap<String, String>;
 29→
 30→/// Full routing state: port → (subdomain → container_ip).
 31→pub struct ProxyState {
 32→    /// Map of port → RouteMap (subdomain → container_ip).
 33→    pub routes: HashMap<u16, RouteMap>,
 34→}
 35→
 36→impl ProxyState {
 37→    /// Build routing table from workspace state and running containers.
 38→    pub fn from_state(state: &WorkspaceState) -> Self {
 39→        let mut routes: HashMap<u16, RouteMap> = HashMap::new();
 40→
 41→        for entry in state.all_workspaces() {
 42→            let container_name = config::container_name(&entry.repo, &entry.branch);
 43→
 44→            // Only route to running containers
 45→            if container::status(&container_name) != container::ContainerStatus::Running {
 46→                continue;
 47→            }
 48→
 49→            let ip = match container::get_ip(&container_name) {
 50→                Some(ip) => ip,
 51→                None => continue,
 52→            };
 53→
 54→            // Load hints to get ports
 55→            let ws_dir = state.workspace_dir(entry);
 56→            let hints = config::load_hints(&ws_dir).unwrap_or_default();
 57→
 58→            let workspace_id = config::workspace_id(&entry.repo, &entry.branch);
 59→            for &port in &hints.ports {
 60→                routes
 61→                    .entry(port)
 62→                    .or_default()
 63→                    .insert(workspace_id.clone(), ip.clone());
 64→            }
 65→        }
 66→
 67→        ProxyState { routes }
 68→    }
 69→
 70→    /// Get the container IP for a given port and subdomain.
 71→    pub fn resolve(&self, port: u16, subdomain: &str) -> Option<&str> {
 72→        self.routes
 73→            .get(&port)
 74→            .and_then(|m| m.get(subdomain))
 75→            .map(|s| s.as_str())
 76→    }
 77→
 78→    /// Get all unique ports that need listeners.
 79→    pub fn ports(&self) -> Vec<u16> {
 80→        self.routes.keys().copied().collect()
 81→    }
 82→}
