 52→/// Start an existing container.
 53→pub fn start(name: &str) -> Result<(), ContainerError> {
 54→    docker_simple("start", name)
 55→}
 56→
 57→/// Stop a running container.
 58→pub fn stop(name: &str) -> Result<(), ContainerError> {
 59→    docker_simple("stop", name)
 60→}
 61→
 62→/// Remove a container (must be stopped first).
 63→pub fn destroy(name: &str) -> Result<(), ContainerError> {
 64→    docker_simple("rm", name)
 65→}
