 67→/// Execute a command inside a running container.
 68→///
 69→/// Returns the exit code of the command.
 70→pub fn exec(name: &str, cmd: &[&str], tty: bool) -> Result<i32, ContainerError> {
 71→    let mut args = vec!["exec".to_string()];
 72→
 73→    if tty {
 74→        args.push("-t".to_string());
 75→    }
 76→
 77→    args.push("-w".to_string());
 78→    args.push(WORKSPACE_MOUNT.to_string());
 79→    args.push(name.to_string());
 80→    args.extend(cmd.iter().map(|s| s.to_string()));
 81→
 82→    let status = Command::new("docker")
 83→        .args(&args)
 84→        .status()
 85→        .map_err(|e| ContainerError::DockerNotFound(e.to_string()))?;
 86→
 87→    Ok(status.code().unwrap_or(1))
 88→}
 89→
 90→/// Check the status of a container.
 91→pub fn status(name: &str) -> ContainerStatus {
 92→    let output = Command::new("docker")
 93→        .args(["inspect", "--format", "{{.State.Running}}", name])
 94→        .output();
 95→
 96→    match output {
 97→        Ok(out) if out.status.success() => {
 98→            let running = String::from_utf8_lossy(&out.stdout).trim().to_string();
 99→            if running == "true" {
100→                ContainerStatus::Running
101→            } else {
102→                ContainerStatus::Stopped
103→            }
104→        }
105→        _ => ContainerStatus::Missing,
106→    }
107→}
108→
109→/// Get the IP address of a running container on the Docker bridge network.
110→pub fn get_ip(name: &str) -> Option<String> {
111→    let output = Command::new("docker")
112→        .args([
113→            "inspect",
114→            "--format",
115→            "{{range .NetworkSettings.Networks}}{{.IPAddress}}{{end}}",
116→            name,
117→        ])
118→        .output()
119→        .ok()?;
120→
121→    if !output.status.success() {
122→        return None;
123→    }
124→
125→    let ip = String::from_utf8_lossy(&output.stdout).trim().to_string();
126→    if ip.is_empty() { None } else { Some(ip) }
127→}
128→
129→/// List all dual-managed containers (name and running status).
130→pub fn list_all() -> Vec<(String, bool)> {
131→    let output = Command::new("docker")
132→        .args([
133→            "ps",
134→            "-a",
135→            "--filter",
136→            "name=dual-",
137→            "--format",
138→            "{{.Names}}\t{{.State}}",
139→        ])
140→        .output();
141→
142→    match output {
143→        Ok(out) if out.status.success() => {
144→            let stdout = String::from_utf8_lossy(&out.stdout);
145→            stdout
146→                .lines()
147→                .filter(|line| !line.is_empty())
148→                .filter_map(|line| {
149→                    let mut parts = line.splitn(2, '\t');
150→                    let name = parts.next()?.to_string();
151→                    let state = parts.next().unwrap_or("");
152→                    Some((name, state == "running"))
153→                })
154→                .collect()
155→        }
156→        _ => Vec::new(),
157→    }
158→}
