160→/// Execute a setup command inside a running container.
161→///
162→/// Runs `docker exec <name> sh -c "<setup_cmd>"` and waits for completion.
163→pub fn exec_setup(name: &str, setup_cmd: &str) -> Result<(), ContainerError> {
164→    let output = Command::new("docker")
165→        .args(build_exec_setup_args(name, setup_cmd))
166→        .output()
167→        .map_err(|e| ContainerError::DockerNotFound(e.to_string()))?;
168→
169→    if !output.status.success() {
170→        let stderr = String::from_utf8_lossy(&output.stderr).to_string();
171→        return Err(ContainerError::Failed {
172→            operation: "exec setup".to_string(),
173→            name: name.to_string(),
174→            stderr,
175→        });
176→    }
177→
178→    Ok(())
179→}
180→
181→/// Build docker exec setup arguments (for testing).
182→pub fn build_exec_setup_args(name: &str, setup_cmd: &str) -> Vec<String> {
183→    vec![
184→        "exec".to_string(),
185→        "-w".to_string(),
186→        WORKSPACE_MOUNT.to_string(),
187→        name.to_string(),
188→        "sh".to_string(),
189→        "-c".to_string(),
190→        setup_cmd.to_string(),
191→    ]
192→}
193→
194→/// Build the docker create arguments (for testing).
195→pub fn build_create_args(
196→    name: &str,
197→    workspace_dir: &Path,
198→    image: &str,
199→    env: &HashMap<String, String>,
200→    anonymous_volumes: &[String],
201→) -> Vec<String> {
202→    let mut args = vec![
203→        "create".to_string(),
204→        "--name".to_string(),
205→        name.to_string(),
206→        // Bind mount workspace
207→        "-v".to_string(),
208→        format!("{}:{WORKSPACE_MOUNT}", workspace_dir.display()),
209→    ];
210→
211→    // Anonymous volumes for directory isolation
212→    for vol in anonymous_volumes {
213→        args.push("-v".to_string());
214→        args.push(format!("{WORKSPACE_MOUNT}/{vol}"));
215→    }
216→
217→    // Environment variables
218→    for (key, value) in env {
219→        args.push("-e".to_string());
220→        args.push(format!("{key}={value}"));
221→    }
222→
223→    // Working directory
224→    args.push("-w".to_string());
225→    args.push(WORKSPACE_MOUNT.to_string());
226→
227→    // Image
228→    args.push(image.to_string());
229→
230→    // Keep container running for docker exec
231→    args.push("sleep".to_string());
232→    args.push("infinity".to_string());
233→
234→    args
235→}
236→
237→/// Build docker exec arguments (for testing).
238→pub fn build_exec_args(name: &str, cmd: &[&str], tty: bool) -> Vec<String> {
239→    let mut args = vec!["exec".to_string()];
240→    if tty {
241→        args.push("-t".to_string());
242→    }
243→    args.push("-w".to_string());
244→    args.push(WORKSPACE_MOUNT.to_string());
245→    args.push(name.to_string());
246→    args.extend(cmd.iter().map(|s| s.to_string()));
247→    args
248→}
