250→fn docker_simple(operation: &str, name: &str) -> Result<(), ContainerError> {
251→    let output = Command::new("docker")
252→        .args([operation, name])
253→        .output()
254→        .map_err(|e| ContainerError::DockerNotFound(e.to_string()))?;
255→
256→    if !output.status.success() {
257→        let stderr = String::from_utf8_lossy(&output.stderr).to_string();
258→        return Err(ContainerError::Failed {
259→            operation: operation.to_string(),
260→            name: name.to_string(),
261→            stderr,
262→        });
263→    }
264→
265→    Ok(())
266→}
