269→pub enum ContainerError {
270→    #[error("docker not found: {0}")]
271→    DockerNotFound(String),
272→
273→    #[error("docker {operation} failed for {name}: {stderr}")]
274→    Failed {
275→        operation: String,
276→        name: String,
277→        stderr: String,
278→    },
