186→#[derive(Debug, thiserror::Error)]
187→pub enum HintsError {
188→    #[error("Failed to read {path}: {err}", path = .0.display(), err = .1)]
189→    ReadError(PathBuf, std::io::Error),
190→
191→    #[error("Failed to write {path}: {err}", path = .0.display(), err = .1)]
192→    WriteError(PathBuf, std::io::Error),
193→
194→    #[error("Failed to parse {path}: {err}", path = .0.display(), err = .1)]
195→    ParseError(PathBuf, toml::de::Error),
196→
197→    #[error("Failed to serialize hints: {0}")]
198→    SerializeError(toml::ser::Error),
199→}
