  5→const WORKSPACE_MOUNT: &str = "/workspace";
  6→
  7→/// Container status.
  8→#[derive(Debug, Clone, PartialEq)]
  9→pub enum ContainerStatus {
 10→    Running,
 11→    Stopped,
 12→    Missing,
 13→}
 14→
 15→/// Create a new Docker container for a workspace.
 16→///
 17→/// - Bind mounts workspace dir to /workspace
 18→/// - Anonymous volumes for directory isolation (configurable)
 19→/// - Sets working directory to /workspace
 20→/// - Passes environment variables via -e flags
 21→/// - Uses bridge network (default) for network namespace isolation
 22→pub fn create(
 23→    name: &str,
 24→    workspace_dir: &Path,
 25→    image: &str,
 26→    env: &HashMap<String, String>,
 27→    anonymous_volumes: &[String],
 28→) -> Result<String, ContainerError> {
 29→    let output = Command::new("docker")
 30→        .args(build_create_args(
 31→            name,
 32→            workspace_dir,
 33→            image,
 34→            env,
 35→            anonymous_volumes,
 36→        ))
 37→        .output()
 38→        .map_err(|e| ContainerError::DockerNotFound(e.to_string()))?;
 39→
 40→    if !output.status.success() {
 41→        let stderr = String::from_utf8_lossy(&output.stderr).to_string();
 42→        return Err(ContainerError::Failed {
 43→            operation: "create".to_string(),
 44→            name: name.to_string(),
 45→            stderr,
 46→        });
 47→    }
 48→
 49→    Ok(name.to_string())
 50→}
 51→
 52→/// Start an existing container.
 53→pub fn start(name: &str) -> Result<(), ContainerError> {
 54→    docker_simple("start", name)
 55→}
 56→
 57→/// Stop a running container.
 58→pub fn stop(name: &str) -> Result<(), ContainerError> {
 59→    docker_simple("stop", name)
 60→}
 61→
 62→/// Remove a container (must be stopped first).
 63→pub fn destroy(name: &str) -> Result<(), ContainerError> {
 64→    docker_simple("rm", name)
 65→}
 66→
 67→/// Execute a command inside a running container.
 68→///
 69→/// Returns the exit code of the command.
 70→pub fn exec(name: &str, cmd: &[&str], tty: bool) -> Result<i32, ContainerError> {
 71→    let mut args = vec!["exec".to_string()];
 72→
 73→    if tty {
 74→        args.push("-t".to_string());
 75→    }
 76→
 77→    args.push("-w".to_string());
